from collections import defaultdict

def rrf(rankings: list[list[str]], k: int = 60, top_n: int = 50) -> list[tuple[str, float]]:
    """Reciprocal Rank Fusion: uses ranks only, raw scores are ignored."""
    fused: dict[str, float] = defaultdict(float)
    for ranking in rankings:                    # one ranked list of doc ids per retriever
        for rank, doc_id in enumerate(ranking, start=1):
            fused[doc_id] += 1.0 / (k + rank)   # k = 60 flattens the gap between #1 and #10
    return sorted(fused.items(), key=lambda x: x[1], reverse=True)[:top_n]

def weighted(bm25: dict[str, float], vec: dict[str, float], alpha: float = 0.5):
    """Alternative: min-max normalize each list, then blend. Tune alpha on labeled queries."""
    def norm(s: dict[str, float]) -> dict[str, float]:
        lo, hi = min(s.values()), max(s.values())
        return {d: (v - lo) / ((hi - lo) or 1.0) for d, v in s.items()}
    b, v = norm(bm25), norm(vec)
    blended = {d: alpha * v.get(d, 0.0) + (1 - alpha) * b.get(d, 0.0) for d in b | v}
    return sorted(blended.items(), key=lambda x: x[1], reverse=True)

bm25_ids   = ["kb-17", "kb-03", "kb-88", "kb-42"]   # from the inverted index
vector_ids = ["kb-42", "kb-17", "kb-91", "kb-05"]   # from the ANN index

for doc_id, score in rrf([bm25_ids, vector_ids])[:3]:
    print(f"{doc_id}  {score:.4f}")
# kb-17 0.0325 (ranks 1 and 2), kb-42 0.0320 (ranks 4 and 1), kb-03 0.0161 (one list only)
